-- Per-user trip sharing. OAuth/ChatGPT consent remains attached to each Viaggio account.
create or replace function public.share_trip_with_email(p_trip_id uuid,p_email text,p_role text default 'editor') returns table(user_id uuid,email text,role text) language plpgsql security definer set search_path=public,auth as $$ declare target_user auth.users%rowtype; normalized_role text:=lower(coalesce(p_role,'editor')); begin if auth.uid() is null then raise exception 'Sessão inválida'; end if; if normalized_role not in ('viewer','editor') then raise exception 'Permissão inválida'; end if; if not exists(select 1 from public.trip_members where trip_id=p_trip_id and user_id=auth.uid() and role='owner') then raise exception 'Somente o proprietário pode compartilhar esta viagem'; end if; select * into target_user from auth.users where lower(auth.users.email)=lower(trim(p_email)) and deleted_at is null limit 1; if target_user.id is null then raise exception 'Nenhuma conta Viaggio encontrada com este e-mail'; end if; if target_user.id=auth.uid() then raise exception 'Você já é o proprietário desta viagem'; end if; insert into public.trip_members(trip_id,user_id,role) values(p_trip_id,target_user.id,normalized_role) on conflict(trip_id,user_id) do update set role=excluded.role; return query select target_user.id,target_user.email::text,normalized_role; end $$;
revoke all on function public.share_trip_with_email(uuid,text,text) from public,anon; grant execute on function public.share_trip_with_email(uuid,text,text) to authenticated;
create or replace function public.list_trip_members(p_trip_id uuid) returns table(user_id uuid,email text,role text,display_name text) language sql stable security definer set search_path=public,auth as $$ select m.user_id,u.email::text,m.role,coalesce(p.name,u.raw_user_meta_data->>'name',split_part(u.email,'@',1))::text from public.trip_members m join auth.users u on u.id=m.user_id left join public.passenger_profiles p on p.user_id=m.user_id where m.trip_id=p_trip_id and public.is_trip_member(p_trip_id) order by case m.role when 'owner' then 0 when 'editor' then 1 else 2 end,4 $$;
revoke all on function public.list_trip_members(uuid) from public,anon; grant execute on function public.list_trip_members(uuid) to authenticated;
drop policy if exists "trip owner edit" on public.trips; drop policy if exists "trip owner or editor edit" on public.trips; create policy "trip owner or editor edit" on public.trips for update using(public.is_trip_member(id,'editor')) with check(public.is_trip_member(id,'editor'));